
#include "lqr_controller.hpp"

#include <cmath>

namespace vehicle_control {

bool tryComputeLqrSteeringCommandRad(
    const LqrInput& input,
    double& steering_command_rad
) noexcept {

    // Reject invalid input values.
    if (!std::isfinite(input.lateral_velocity_error_mps) ||
        !std::isfinite(input.yaw_rate_error_rad_s) ||
        !std::isfinite(input.lateral_error_m) ||
        !std::isfinite(input.heading_error_rad) ||
        !std::isfinite(input.feedforward_steering_rad)) {
        return false;
    }

    // LQR feedback gains generated by MATLAB.
    constexpr double k_vy   = 0.47250809213142853;
    constexpr double k_r    = 0.29445115549682072;
    constexpr double k_ey   = 4.8304589153964894;
    constexpr double k_epsi = 4.9572996709829944;

    // Calculate state-feedback correction.
    const double feedback =
        k_vy * input.lateral_velocity_error_mps
        + k_r * input.yaw_rate_error_rad_s
        + k_ey * input.lateral_error_m
        + k_epsi * input.heading_error_rad;

    // Calculate requested steering.
    const double command =
        input.feedforward_steering_rad - feedback;

    // Reject invalid calculated output.
    if (!std::isfinite(command)) {
        return false;
    }

    steering_command_rad = command;

    return true;
}

} // namespace vehicle_control
